  const wait=async()=>{
    for(let i=0;i<120;i++){
      if(typeof kpi2RenderMonthly==='function' && typeof KPI2_DAILY_SEED!=='undefined' && typeof KPI2_MONTH_SEED!=='undefined')return true;
      await new Promise(r=>setTimeout(r,100));
    }
    return false;
  };
  (async()=>{
    if(!(await wait())){console.error('KPI V35.10.27: base V35.10.26 não ficou disponível.');return}
    try{
      KPI2_META.dispKm=.075;
      KPI2_META.dispTempo=.15;
      KPI2_META.cxViagem=254.50;
      KPI2_META.cxSemVan=252.14;
      KPI2_META.entregas=15.36;
      KPI2_META.dropsize=13.72;
      KPI2_META.ocupacao=.77;
      KPI2_META.utilizacao=.6684;
      KPI2_DAILY_SEED.splice(0,KPI2_DAILY_SEED.length,...KPI27_DAILY);
      const KPI27_STORAGE='dws_kpi_daily_v5';
      try{if(!localStorage.getItem(KPI27_STORAGE)){const old=localStorage.getItem('dws_kpi_daily_v4');if(old)localStorage.setItem(KPI27_STORAGE,old)}}catch(e){}
      kpi2LoadSaved=function(){try{const x=JSON.parse(localStorage.getItem(KPI27_STORAGE)||'[]');return Array.isArray(x)?x:[]}catch(e){return []}};
      kpi2SaveSaved=function(x){try{localStorage.setItem(KPI27_STORAGE,JSON.stringify(x))}catch(e){}};
      const abbr=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
      const simpleMean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:null;
      const savedInMonth=mi=>kpi2LoadSaved().some(r=>!r.deleted && String(r.date||'').startsWith(`2026-${String(mi+1).padStart(2,'0')}-`));
      const latestDataMonth=()=>{const ms=kpi2Records().map(r=>Number(String(r.date||'').slice(5,7))-1).filter(v=>Number.isInteger(v)&&v>=0&&v<12);return ms.length?Math.max(...ms):-1};
      kpi2DailyMemory=function(key,mi){
        const rows=kpi2MonthRows(mi).filter(r=>Number.isFinite(Number(r.results?.[key])));
        if(!rows.length)return null;
        const vals=rows.map(r=>Number(r.results[key]));
        let n=0,d=0,missing=0;
        for(const r of rows){const v=Number(r.results[key]),base=Number(r.bases?.[key]);if(!(base>0)){missing++;continue}d+=base;n+=(key==='dispKm'||key==='dispTempo')?(1+v)*base:v*base}
        if(!missing && d>0)return {v:(key==='dispKm'||key==='dispTempo')?n/d-1:n/d,n,d,complete:true,source:'Memória diária',days:rows.length,missing:0};
        return {v:simpleMean(vals),n:null,d:null,complete:false,source:'Resultado diário provisório',days:rows.length,missing};
      };
      kpi2MonthMemory=function(key,mi){
        const official=KPI2_MONTH_SEED[String(mi)]?.[key],hasEdit=savedInMonth(mi);
        if(mi<=7 && official && !hasEdit)return {...official,complete:true,source:'Memória oficial',official:true};
        const daily=kpi2DailyMemory(key,mi);
        if(mi<=7 && official && hasEdit && (!daily||!daily.complete))return {...official,complete:true,source:'Memória oficial',official:true,pendingEdit:true,note:'Há edição diária sem base suficiente; o acumulado mantém a memória oficial até completar a base.'};
        return daily;
      };
      kpi2YearMemory=function(key){
        let n=0,d=0,any=false;const used=[],pending=[];
        for(let mi=0;mi<12;mi++){const x=kpi2MonthMemory(key,mi);if(!x)continue;if(x.complete&&Number.isFinite(Number(x.n))&&Number(x.d)>0){any=true;n+=Number(x.n);d+=Number(x.d);used.push(mi);if(x.pendingEdit)pending.push(mi)}else pending.push(mi)}
        if(!any||!d)return {v:null,n:null,d:null,complete:false,used,pending};
        return {v:(key==='dispKm'||key==='dispTempo')?n/d-1:n/d,n,d,complete:pending.length===0,used,pending};
      };
      const css=document.createElement('style');css.textContent='.kpi27-val{font-size:9px;font-weight:900;border:1px solid #2d5e4b;background:#0b2a20;color:#83e6bb;border-radius:999px;padding:5px 8px;cursor:pointer;white-space:nowrap}.kpi27-val.partial{border-color:#725b2b;background:#302713;color:#ffd36a}.kpi27-partmark{display:inline-block;margin-left:4px;color:#ffc857;font-size:11px}.kpi27-validate-btn{height:34px;border:1px solid #315c7c;border-radius:10px;background:#0c2942;color:#dcecff;padding:0 12px;font-size:10px;font-weight:900;cursor:pointer}.kpi27-modal{position:fixed;inset:0;z-index:100001;background:rgba(1,8,16,.82);display:none;align-items:center;justify-content:center;padding:18px}.kpi27-modal.open{display:flex}.kpi27-box{width:min(1040px,96vw);max-height:90vh;overflow:auto;background:#081c30;border:1px solid #2d5878;border-radius:20px}.kpi27-head{display:flex;justify-content:space-between;align-items:center;padding:16px 18px;border-bottom:1px solid #21405b}.kpi27-head h3{margin:0;font-size:17px}.kpi27-close{border:0;background:transparent;color:#bdd5e9;font-size:25px;cursor:pointer}.kpi27-body{padding:16px 18px}.kpi27-note{color:#89a9c5;font-size:10px;line-height:1.5;margin:0 0 12px}.kpi27-table{width:100%;border-collapse:collapse}.kpi27-table th,.kpi27-table td{padding:10px 8px;border-bottom:1px solid #1c3952;font-size:10px;text-align:center}.kpi27-table th{background:#153a5b;color:#fff;text-transform:uppercase;font-size:9px}.kpi27-table td:first-child,.kpi27-table th:first-child{text-align:left}.kpi27-ok{color:#25dda8;font-weight:900}.kpi27-warn{color:#ffc857;font-weight:900}.kpi2-table th:nth-child(4),.kpi2-table td:nth-child(4){width:100px}.kpi2-table th:nth-child(n+5),.kpi2-table td:nth-child(n+5){width:55px}@media(max-width:1050px){.kpi2-table{min-width:1325px}}';document.head.appendChild(css);
      const thead=document.querySelector('#kpi2MonthlyPane .kpi2-table thead tr');if(thead&&!thead.querySelector('[data-kpi27-valhead]')){const th=document.createElement('th');th.dataset.kpi27Valhead='1';th.textContent='Validação Ano';thead.insertBefore(th,thead.children[3]||null)}
      const cardHead=document.querySelector('#kpi2MonthlyPane .kpi2-cardhead');if(cardHead&&!document.getElementById('kpi27ValidateAll')){const btn=document.createElement('button');btn.id='kpi27ValidateAll';btn.type='button';btn.className='kpi27-validate-btn';btn.textContent='Validar acumulado';btn.addEventListener('click',()=>kpi27OpenValidation());cardHead.appendChild(btn)}
      const modal=document.createElement('div');modal.id='kpi27Modal';modal.className='kpi27-modal';modal.innerHTML='<div class="kpi27-box"><div class="kpi27-head"><h3 id="kpi27Title">Validação do acumulado 2026</h3><button class="kpi27-close" id="kpi27Close" type="button">×</button></div><div class="kpi27-body"><p class="kpi27-note">O acumulado anual só soma meses com memória completa. Mês sem base fica visível no mensal, mas não é misturado no acumulado até a memória ser concluída.</p><div id="kpi27Content"></div></div></div>';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('open')});modal.querySelector('#kpi27Close').addEventListener('click',()=>modal.classList.remove('open'));
      window.kpi27OpenValidation=function(key){const content=document.getElementById('kpi27Content'),title=document.getElementById('kpi27Title');if(key){const y=kpi2YearMemory(key),rows=[];title.textContent=`Validação 2026 • ${KPI2_LABELS[key]}`;for(let mi=0;mi<12;mi++){const x=kpi2MonthMemory(key,mi);if(!x)continue;const st=x.complete?(x.pendingEdit?'⚠ Edição pendente':'✓ Memória válida'):'⚠ Base incompleta';rows.push(`<tr><td>${KPI2_MONTHS[mi]}</td><td>${kpi2Fmt(key,x.v)}</td><td>${x.source||'—'}</td><td class="${x.complete&&!x.pendingEdit?'kpi27-ok':'kpi27-warn'}">${st}</td></tr>`)}const formula=(key==='dispKm'||key==='dispTempo')?'(Σ realizado ÷ Σ base) − 1':'Σ numerador ÷ Σ base';content.innerHTML=`<div style="margin-bottom:12px;font-size:11px"><b>Acumulado validado:</b> ${y.v===null?'—':kpi2Fmt(key,y.v)} &nbsp; <span style="color:#789bb8">• ${formula}</span></div><table class="kpi27-table"><thead><tr><th>Mês</th><th>Resultado</th><th>Origem</th><th>Validação</th></tr></thead><tbody>${rows.join('')}</tbody></table>`}else{title.textContent='Validação do acumulado 2026';content.innerHTML=`<table class="kpi27-table"><thead><tr><th>Indicador</th><th>Acumulado</th><th>Meses validados</th><th>Pendente</th><th>Status</th></tr></thead><tbody>${KPI2_KEYS.map(k=>{const y=kpi2YearMemory(k),pend=y.pending||[],used=y.used||[],last=used.length?Math.max(...used):-1,latest=latestDataMonth();const status=pend.length?'⚠ PARCIAL':(last>=0&&last<latest?`✓ VALIDADO ATÉ ${abbr[last].toUpperCase()}`:'✓ VALIDADO');return `<tr><td>${KPI2_LABELS[k]}</td><td>${y.v===null?'—':kpi2Fmt(k,y.v)}</td><td>${used.length?used.map(i=>abbr[i]).join(', '):'—'}</td><td>${pend.length?pend.map(i=>abbr[i]).join(', '):'—'}</td><td class="${pend.length?'kpi27-warn':'kpi27-ok'}">${status}</td></tr>`}).join('')}</tbody></table>`}modal.classList.add('open')};
      kpi2RenderMonthly=function(){const body=document.getElementById('kpi2MonthBody');if(!body)return;body.innerHTML=KPI2_KEYS.map(key=>{const y=kpi2YearMemory(key),pend=y?.pending||[],used=y?.used||[],last=used.length?Math.max(...used):-1,latest=latestDataMonth();const yCls=!y||y.v===null?'kpi2-empty':kpi2Good(key,y.v)?'kpi2-good':'kpi2-bad';const valCls=pend.length?'kpi27-val partial':'kpi27-val';const valTxt=pend.length?`⚠ ${pend.map(i=>abbr[i]).join(', ')}`:(last>=0&&last<latest?`✓ Até ${abbr[last]}`:'✓ Validado');let cells=`<td>${KPI2_LABELS[key]}</td><td>${kpi2FmtMeta(key)}</td><td class="kpi2-acum ${yCls}">${y&&y.v!==null?kpi2Fmt(key,y.v):'—'}</td><td><button type="button" class="${valCls}" onclick="kpi27OpenValidation('${key}')">${valTxt}</button></td>`;for(let mi=0;mi<12;mi++){const x=kpi2MonthMemory(key,mi);if(!x){cells+='<td class="kpi2-empty">—</td>';continue}const cls=kpi2Good(key,x.v)?'kpi2-good':'kpi2-bad';const mark=x.complete?'':'<span class="kpi27-partmark" title="Resultado provisório: memória/base incompleta">●</span>';cells+=`<td class="${cls}">${kpi2Fmt(key,x.v)}${mark}</td>`}return `<tr>${cells}</tr>`}).join('')};
      kpi2RenderMonthly();kpi2RenderDaily();console.info('KPI V35.10.27 ativo: Jan-Set importados + validação anual por memória.');
    }catch(e){console.error('Falha KPI V35.10.27',e)}
  })();
